          : "min-h-14 py-2 md:rounded-t-[14px]",
      )}
    >
      <AppSidebarToggle />
      <WorkspaceHeaderSlot>
        {children ?? (
          <>
            <span
              aria-hidden="true"
              className="h-5 w-px shrink-0 bg-neutral-200"
